[standards/application/event-driven/STD-APP-EVT-003-dotnet-event-sourcing.md#marten-event-store-configuration]

### Marten Event Store Configuration

**Program.cs - Dependency Injection Setup:**

```csharp
using Marten;
using Marten.Events.Projections;
using Marten.Services;
using Weasel.Core;

var builder = WebApplication.CreateBuilder(args);

// Configure Marten as document store and event store
builder.Services.AddMarten(options =>
{
    // PostgreSQL connection string
    options.Connection(builder.Configuration.GetConnectionString("EventStore")
        ?? "Host=localhost;Database=eventstore;Username=postgres;Password=postgres");

    // Configure event store
    options.Events.StreamIdentity = StreamIdentity.AsGuid;

    // Use System.Text.Json for serialization
    options.UseSystemTextJsonForSerialization(
        enumStorage: EnumStorage.AsString,
        casing: Casing.CamelCase);

    // Configure projections
    options.Projections.Add<ClaimProjection>(ProjectionLifecycle.Async);
    options.Projections.Add<ClaimSummaryProjection>(ProjectionLifecycle.Inline);

    // Auto-create database schema in development
    if (builder.Environment.IsDevelopment())
    {
        options.AutoCreateSchemaObjects = AutoCreate.All;
    }
    else
    {
        options.AutoCreateSchemaObjects = AutoCreate.None;
    }

    // Enable optimistic concurrency
    options.UseOptimisticConcurrency = true;

    // Configure metadata
    options.Events.MetadataConfig.HeadersEnabled = true;
    options.Events.MetadataConfig.CorrelationIdEnabled = true;
    options.Events.MetadataConfig.CausationIdEnabled = true;
})
// Add async projection daemon (runs projections in background)
.AddAsyncDaemon(DaemonMode.HotCold)
// Optimize for HTTP workloads
.OptimizeArtifactWorkflow()
// Use lightweight sessions
.UseLightweightSessions();

builder.Services.AddControllers();

var app = builder.Build();
app.MapControllers();
app.Run();
```

