[standards/application/event-driven/STD-APP-EVT-003-dotnet-event-sourcing.md#event-and-aggregate-design-patterns]

### Event and Aggregate Design Patterns

**Domain Event Base Class:**

```csharp
using System;

public abstract record DomainEvent
{
    /// <summary>
    /// Unique identifier for this event
    /// </summary>
    public Guid EventId { get; init; } = Guid.NewGuid();

    /// <summary>
    /// When the event occurred (set by aggregate)
    /// </summary>
    public DateTime Timestamp { get; init; } = DateTime.UtcNow;

    /// <summary>
    /// Event schema version for evolution
    /// </summary>
    public int Version { get; init; } = 1;

    /// <summary>
    /// User or system that caused this event
    /// </summary>
    public string? CausedBy { get; init; }
}
```

**Aggregate Root Base Class:**

```csharp
using Marten;
using System;
using System.Collections.Generic;
using System.Linq;

public abstract class AggregateRoot<TId>
{
    /// <summary>
    /// Aggregate identifier
    /// </summary>
    public TId Id { get; protected set; } = default!;

    /// <summary>
    /// Current version (from event stream)
    /// </summary>
    public int Version { get; protected set; }

    /// <summary>
    /// Uncommitted events pending storage
    /// </summary>
    private readonly List<object> _uncommittedEvents = new();

    /// <summary>
    /// Get uncommitted events for persistence
    /// </summary>
    public IEnumerable<object> GetUncommittedEvents() => _uncommittedEvents;

    /// <summary>
    /// Clear uncommitted events after persistence
    /// </summary>
    public void MarkEventsAsCommitted() => _uncommittedEvents.Clear();

    /// <summary>
    /// Apply event and add to uncommitted list
    /// </summary>
    protected void RaiseEvent(object @event)
    {
        ApplyEvent(@event);
        _uncommittedEvents.Add(@event);
    }

    /// <summary>
    /// Apply event to aggregate state (override in derived classes)
    /// </summary>
    protected abstract void ApplyEvent(object @event);

    /// <summary>
    /// Load aggregate from event history
    /// </summary>
    public void LoadFromHistory(IEnumerable<object> history)
    {
        foreach (var @event in history)
        {
            ApplyEvent(@event);
            Version++;
        }
    }
}
```

