[standards/application/event-driven/STD-APP-EVT-003-dotnet-event-sourcing.md#step-12-implement-aggregate-root]

#### Step 1.2: Implement Aggregate Root

Create aggregate that rebuilds state from events:

```csharp
public class Claim : AggregateRoot<Guid>
{
    // Current state (rebuilt from events)
    public string ClaimNumber { get; private set; } = string.Empty;
    public string PatientId { get; private set; } = string.Empty;
    public decimal Amount { get; private set; }
    public ClaimStatus Status { get; private set; }
    public DateTime ServiceDate { get; private set; }
    public DateTime? ApprovedAt { get; private set; }
    public string? ApprovedBy { get; private set; }

    // Required for Marten
    private Claim() { }

    // Factory method to create new claim
    public static Claim Submit(
        string claimNumber,
        string patientId,
        decimal amount,
        DateTime serviceDate,
        string submittedBy)
    {
        var claim = new Claim();
        claim.RaiseEvent(new ClaimSubmitted
        {
            ClaimId = Guid.NewGuid(),
            ClaimNumber = claimNumber,
            PatientId = patientId,
            Amount = amount,
            ServiceDate = serviceDate,
            CausedBy = submittedBy
        });
        return claim;
    }

    // Command methods
    public void Approve(string approvedBy, string reason)
    {
        if (Status != ClaimStatus.Submitted)
            throw new InvalidOperationException($"Cannot approve claim in status {Status}");

        RaiseEvent(new ClaimApproved
        {
            ClaimId = Id,
            ApprovedBy = approvedBy,
            ApprovalReason = reason,
            CausedBy = approvedBy
        });
    }

    public void Reject(string rejectedBy, string reason)
    {
        if (Status != ClaimStatus.Submitted)
            throw new InvalidOperationException($"Cannot reject claim in status {Status}");

        RaiseEvent(new ClaimRejected
        {
            ClaimId = Id,
            RejectedBy = rejectedBy,
            RejectionReason = reason,
            CausedBy = rejectedBy
        });
    }

    public void AdjustAmount(decimal newAmount, string adjustedBy, string reason)
    {
        if (Status != ClaimStatus.Submitted)
            throw new InvalidOperationException("Can only adjust submitted claims");

        if (newAmount < 0)
            throw new ArgumentException("Amount cannot be negative");

        RaiseEvent(new ClaimAmountAdjusted
        {
            ClaimId = Id,
            OldAmount = Amount,
            NewAmount = newAmount,
            AdjustedBy = adjustedBy,
            Reason = reason,
            CausedBy = adjustedBy
        });
    }

    // Event application (rebuilds state)
    protected override void ApplyEvent(object @event)
    {
        switch (@event)
        {
            case ClaimSubmitted e:
                Apply(e);
                break;
            case ClaimApproved e:
                Apply(e);
                break;
            case ClaimRejected e:
                Apply(e);
                break;
            case ClaimAmountAdjusted e:
                Apply(e);
                break;
        }
    }

    private void Apply(ClaimSubmitted e)
    {
        Id = e.ClaimId;
        ClaimNumber = e.ClaimNumber;
        PatientId = e.PatientId;
        Amount = e.Amount;
        ServiceDate = e.ServiceDate;
        Status = ClaimStatus.Submitted;
    }

    private void Apply(ClaimApproved e)
    {
        Status = ClaimStatus.Approved;
        ApprovedBy = e.ApprovedBy;
        ApprovedAt = e.Timestamp;
    }

    private void Apply(ClaimRejected e)
    {
        Status = ClaimStatus.Rejected;
    }

    private void Apply(ClaimAmountAdjusted e)
    {
        Amount = e.NewAmount;
    }
}

public enum ClaimStatus
{
    Submitted,
    Approved,
    Rejected
}
```

