#### Step 2.2: Implement Command Handlers

```csharp
using Marten;
using MediatR;
using System.Diagnostics;

public class SubmitClaimHandler : IRequestHandler<SubmitClaimCommand, Guid>
{
    private readonly IDocumentSession _session;
    private readonly ILogger<SubmitClaimHandler> _logger;
    private static readonly ActivitySource ActivitySource = new("ClaimService");

    public SubmitClaimHandler(IDocumentSession session, ILogger<SubmitClaimHandler> logger)
    {
        _session = session;
        _logger = logger;
    }

    public async Task<Guid> Handle(SubmitClaimCommand request, CancellationToken cancellationToken)
    {
        using var activity = ActivitySource.StartActivity("SubmitClaim", ActivityKind.Internal);

        // Create aggregate
        var claim = Claim.Submit(
            request.ClaimNumber,
            request.PatientId,
            request.Amount,
            request.ServiceDate,
            request.SubmittedBy);

        // Append events to stream
        var streamId = claim.Id;
        _session.Events.StartStream<Claim>(streamId, claim.GetUncommittedEvents().ToArray());

        // Save to event store
        await _session.SaveChangesAsync(cancellationToken);

        _logger.LogInformation(
            "Claim submitted: ClaimId={ClaimId}, ClaimNumber={ClaimNumber}",
            claim.Id, claim.ClaimNumber);

        activity?.SetTag("claim.id", claim.Id);
        activity?.SetTag("claim.number", claim.ClaimNumber);

        return claim.Id;
    }
}

public class ApproveClaimHandler : IRequestHandler<ApproveClaimCommand>
{
    private readonly IDocumentSession _session;
    private readonly ILogger<ApproveClaimHandler> _logger;

    public ApproveClaimHandler(IDocumentSession session, ILogger<ApproveClaimHandler> logger)
    {
        _session = session;
        _logger = logger;
    }

    public async Task Handle(ApproveClaimCommand request, CancellationToken cancellationToken)
    {
        // Load aggregate from event stream
        var claim = await _session.Events.AggregateStreamAsync<Claim>(
            request.ClaimId,
            cancellationToken: cancellationToken);

        if (claim == null)
            throw new InvalidOperationException($"Claim {request.ClaimId} not found");

        // Execute command (raises events)
        claim.Approve(request.ApprovedBy, request.Reason);

        // Append new events to stream
        _session.Events.Append(request.ClaimId, claim.GetUncommittedEvents().ToArray());

        // Save with optimistic concurrency check
        await _session.SaveChangesAsync(cancellationToken);

        _logger.LogInformation(
            "Claim approved: ClaimId={ClaimId}, ApprovedBy={ApprovedBy}",
            request.ClaimId, request.ApprovedBy);
    }
}
```

