#### Step 3.2: Implement Async Projection (Eventual Consistency)

```csharp
using Marten.Events.Aggregation;

public class ClaimProjection : SingleStreamProjection<ClaimReadModel>
{
    public ClaimProjection()
    {
        // Projection is identified by claim ID
        Identity<ClaimSubmitted>(x => x.ClaimId);
        Identity<ClaimApproved>(x => x.ClaimId);
        Identity<ClaimRejected>(x => x.ClaimId);
        Identity<ClaimAmountAdjusted>(x => x.ClaimId);
    }

    public ClaimReadModel Create(ClaimSubmitted @event)
    {
        return new ClaimReadModel
        {
            Id = @event.ClaimId,
            ClaimNumber = @event.ClaimNumber,
            PatientId = @event.PatientId,
            Amount = @event.Amount,
            ServiceDate = @event.ServiceDate,
            Status = ClaimStatus.Submitted,
            SubmittedAt = @event.Timestamp
        };
    }

    public void Apply(ClaimApproved @event, ClaimReadModel projection)
    {
        projection.Status = ClaimStatus.Approved;
        projection.ApprovedBy = @event.ApprovedBy;
        projection.ApprovedAt = @event.Timestamp;
    }

    public void Apply(ClaimRejected @event, ClaimReadModel projection)
    {
        projection.Status = ClaimStatus.Rejected;
    }

    public void Apply(ClaimAmountAdjusted @event, ClaimReadModel projection)
    {
        projection.Amount = @event.NewAmount;
    }
}
```

