    public async Task<List<ClaimReadModel>> GetClaimsByPatientAsync(string patientId)
    {
        return await _session.Query<ClaimReadModel>()
            .Where(c => c.PatientId == patientId)
            .OrderByDescending(c => c.SubmittedAt)
            .ToListAsync();
