```csharp
using Marten.Events;

public class ClaimEventUpcaster : IEventUpcaster
{
    public Type[] CanUpcast => new[] { typeof(ClaimSubmittedV1) };

    public object Upcast(object @event)
    {
        if (@event is ClaimSubmittedV1 v1)
        {
            return new ClaimSubmittedV2
            {
                ClaimId = v1.ClaimId,
                ClaimNumber = v1.ClaimNumber,
                PatientId = "UNKNOWN", // Default for missing field
                Amount = v1.Amount,
                ServiceDate = v1.Timestamp.Date // Infer from timestamp
            };
        }

        return @event;
    }
}

// Register upcaster in Program.cs
builder.Services.AddMarten(options =>
{
    options.Events.Upcast<ClaimSubmittedV1, ClaimSubmittedV2>(
        old => new ClaimSubmittedV2
        {
            ClaimId = old.ClaimId,
            ClaimNumber = old.ClaimNumber,
            PatientId = "UNKNOWN",
            Amount = old.Amount,
            ServiceDate = old.Timestamp.Date
        });
});
