    [Fact]
    public async Task SubmitAndApproveClaim_ShouldPersistEventsCorrectly()
    {
        // Arrange
        await using var session = _store!.LightweightSession();

        // Act - Submit claim
        var claimId = Guid.NewGuid();
        session.Events.StartStream<Claim>(
            claimId,
            new ClaimSubmitted
            {
                ClaimId = claimId,
                ClaimNumber = "CLM-001",
                PatientId = "P12345",
                Amount = 100m,
                ServiceDate = DateTime.Today,
                CausedBy = "user1"
