        // Act - Approve claim
        var claim = await session.Events.AggregateStreamAsync<Claim>(claimId);
        claim!.Approve("admin1", "Valid");
        session.Events.Append(claimId, claim.GetUncommittedEvents().ToArray());
        await session.SaveChangesAsync();

        // Assert - Reload and verify
        var reloaded = await session.Events.AggregateStreamAsync<Claim>(claimId);
        Assert.NotNull(reloaded);
        Assert.Equal(ClaimStatus.Approved, reloaded.Status);
        Assert.Equal("admin1", reloaded.ApprovedBy);

        // Verify event count
        var events = await session.Events.FetchStreamAsync(claimId);
        Assert.Equal(2, events.Count);
    }

    public async Task DisposeAsync()
    {
        _store?.Dispose();
        if (_postgres != null)
            await _postgres.DisposeAsync();
    }
}
