#### Step 6.1: Monitor Projection Lag

```csharp
using Marten.Events.Daemon;

public class ProjectionHealthCheck : IHealthCheck
{
    private readonly IProjectionCoordinator _coordinator;

    public ProjectionHealthCheck(IProjectionCoordinator coordinator)
    {
        _coordinator = coordinator;
    }

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        var status = await _coordinator.StatusAsync();

        var laggingProjections = status.Shards
            .Where(s => s.EventsPerSecond < 100 && s.EventsProcessed < s.SequenceCount)
            .ToList();

        if (laggingProjections.Any())
        {
            return HealthCheckResult.Degraded(
                $"{laggingProjections.Count} projections lagging behind event stream");
        }

        return HealthCheckResult.Healthy("All projections up to date");
    }
}
```

