### Complete Working Example

This example demonstrates a complete event-sourced claims processing system.

**ClaimsController.cs - API Endpoints:**

```csharp
using MediatR;
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class ClaimsController : ControllerBase
{
    private readonly IMediator _mediator;
    private readonly ClaimQueryService _queryService;
    private readonly ILogger<ClaimsController> _logger;

    public ClaimsController(
        IMediator mediator,
        ClaimQueryService queryService,
        ILogger<ClaimsController> logger)
    {
        _mediator = mediator;
        _queryService = queryService;
        _logger = logger;
    }

    /// <summary>
    /// Submit a new claim (Command)
    /// </summary>
    [HttpPost]
    public async Task<ActionResult<Guid>> SubmitClaim([FromBody] SubmitClaimCommand command)
    {
        var claimId = await _mediator.Send(command);
        return CreatedAtAction(nameof(GetClaim), new { id = claimId }, claimId);
    }

    /// <summary>
    /// Approve a claim (Command)
    /// </summary>
    [HttpPost("{id}/approve")]
    public async Task<IActionResult> ApproveClaim(
        Guid id,
        [FromBody] ApproveClaimRequest request)
    {
        await _mediator.Send(new ApproveClaimCommand
        {
            ClaimId = id,
            ApprovedBy = User.Identity?.Name ?? "system",
            Reason = request.Reason
        });

        return NoContent();
    }

    /// <summary>
    /// Get claim details (Query from read model)
    /// </summary>
    [HttpGet("{id}")]
    public async Task<ActionResult<ClaimReadModel>> GetClaim(Guid id)
    {
        var claim = await _queryService.GetClaimAsync(id);

        if (claim == null)
            return NotFound();

        return Ok(claim);
    }

    /// <summary>
    /// Get claim event history (debugging/audit)
    /// </summary>
    [HttpGet("{id}/history")]
    public async Task<ActionResult<ClaimHistoryResponse>> GetClaimHistory(
        Guid id,
        [FromServices] IDocumentStore store)
    {
        await using var session = store.QuerySession();
        var events = await session.Events.FetchStreamAsync(id);

        var history = new ClaimHistoryResponse
        {
            ClaimId = id,
            Events = events.Select(e => new EventInfo
            {
                EventType = e.EventType.Name,
                Timestamp = e.Timestamp,
                Version = e.Version,
                Data = e.Data
            }).ToList()
        };

        return Ok(history);
    }

    /// <summary>
    /// Get claims by patient (Query)
    /// </summary>
    [HttpGet("by-patient/{patientId}")]
    public async Task<ActionResult<List<ClaimReadModel>>> GetClaimsByPatient(string patientId)
    {
        var claims = await _queryService.GetClaimsByPatientAsync(patientId);
        return Ok(claims);
    }

    /// <summary>
    /// Temporal query: Get claim state at specific time
    /// </summary>
    [HttpGet("{id}/at/{timestamp}")]
    public async Task<ActionResult<Claim>> GetClaimAtTimestamp(
        Guid id,
        DateTime timestamp,
        [FromServices] IDocumentStore store)
    {
        await using var session = store.QuerySession();

        // Fetch events up to timestamp
        var events = await session.Events.FetchStreamAsync(id);
        var eventsUpToTimestamp = events
            .Where(e => e.Timestamp <= timestamp)
            .Select(e => e.Data)
            .ToList();

        if (!eventsUpToTimestamp.Any())
            return NotFound();

        // Rebuild aggregate state at that point in time
        var claim = new Claim();
        claim.LoadFromHistory(eventsUpToTimestamp);

        return Ok(new
        {
            ClaimId = claim.Id,
            Status = claim.Status,
            Amount = claim.Amount,
            AsOfTimestamp = timestamp,
            EventCount = eventsUpToTimestamp.Count
        });
    }
}

public record ApproveClaimRequest
{
    public string Reason { get; init; } = string.Empty;
}

public record ClaimHistoryResponse
{
    public Guid ClaimId { get; init; }
    public List<EventInfo> Events { get; init; } = new();
}

public record EventInfo
{
    public string EventType { get; init; } = string.Empty;
    public DateTime Timestamp { get; init; }
    public long Version { get; init; }
    public object Data { get; init; } = new();
}
