### Integration with Kafka for Cross-Context Events

**Publishing Events from Projections to Kafka:**

```csharp
using Confluent.Kafka;
using Marten.Events.Projections;

public class ClaimEventPublisher : IProjection
{
    private readonly IProducer<string, string> _kafkaProducer;
    private readonly ILogger<ClaimEventPublisher> _logger;

    public ClaimEventPublisher(
        IProducer<string, string> kafkaProducer,
        ILogger<ClaimEventPublisher> logger)
    {
        _kafkaProducer = kafkaProducer;
        _logger = logger;
    }

    public void Apply(
        IDocumentOperations operations,
        IReadOnlyList<StreamAction> streams)
    {
        foreach (var stream in streams)
        {
            foreach (var @event in stream.Events)
            {
                // Only publish specific events to Kafka
                if (@event.Data is ClaimApproved approved)
                {
                    PublishToKafka("claims.approved", approved);
                }
                else if (@event.Data is ClaimRejected rejected)
                {
                    PublishToKafka("claims.rejected", rejected);
                }
            }
        }
    }

    private void PublishToKafka(string topic, object eventData)
    {
        try
        {
            var message = new Message<string, string>
            {
                Key = Guid.NewGuid().ToString(),
                Value = JsonSerializer.Serialize(eventData)
            };

            _kafkaProducer.Produce(topic, message, deliveryReport =>
            {
                if (deliveryReport.Error.IsError)
                {
                    _logger.LogError(
                        "Failed to publish to Kafka: {Error}",
                        deliveryReport.Error.Reason);
                }
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error publishing event to Kafka");
        }
    }
}
